      if(sm){ html+=chead(sm[1], 'Section '+sm[1], sm[2]); i++; continue; }
      if(b.style==='Heading2'){ html+='<h2 class="ds-h2">'+inline(t)+'</h2>'; i++; continue; }
      if(b.style==='Heading3'){ html+='<h3 class="ds-h3">'+inline(t)+'</h3>'; i++; continue; }
      if(/^ROLE PROFILE/i.test(t)){ html+='<div class="ds-divider"><span>'+esc(t)+'</span></div>'; i++; continue; }
      if(/^Your briefing:/i.test(t)){ html+='<div class="ds-briefing">'+inline(t)+'</div>'; i++; continue; }
      if(/^(Remember:|Foundation Summary|Foundation Module)/i.test(t)){ html+='<p class="ds-note">'+inline(t)+'</p>'; i++; continue; }
      html+='<p class="ds-p">'+inline(t)+'</p>'; i++;
